61	static void fallback_exec(char **argv)
62	{
63	    static const char fallback[] = SANDSTONE_FALLBACK_EXEC;
64	    char buf[PATH_MAX];
65	
66	    if (strlen(fallback) == 0)
67	        return;
68	
69	    // AT_EXECFN was added to Linux on 2.6.27, so we should be fine. We use
70	    // AT_EXECFN instead of argv[0] because the kernel always gives us the full
71	    // path to the executable, whereas argv[0] is what our parent process
72	    // decided to give us. Alternative: readlink("/proc/self/exe").
73	    const char *execfn = reinterpret_cast<const char *>(getauxval(AT_EXECFN));
74	    if (!execfn || strlen(execfn) >= sizeof(buf))
75	        return;
76	
77	    strcpy(buf, execfn);
78	    char *lastslash = strrchr(buf, '/');
79	    if (!lastslash || (buf + sizeof(buf) - lastslash) < sizeof(fallback))
80	        return;
81	
82	    *++lastslash = '\0';
83	    strcpy(lastslash, fallback);
84	
85	    // Security check: only execute that binary if it is either owned by the
86	    // current user, by root, or by the same user that owns the current
87	    // executable.
88	    struct stat st;
89	    int fd = open(buf, O_PATH);
90	    if (fd == -1)
91	        return;
92	    if (fstat(fd, &st) == -1)
93	        goto noexec;
94	    if (st.st_uid != 0 && st.st_uid != getuid()) {
95	        struct stat stself;
96	        if (stat("/proc/self/exe", &stself) == -1)
97	            goto noexec;
98	        if (st.st_uid != stself.st_uid)
99	            goto noexec;
100	    }
101	
102	    IGNORE_RETVAL(fexecve(fd, argv, environ));
103	
104	noexec:
105	    close(fd);
106	}
