13	// 软件参考：使用 fmaf 逐元素计算（单次舍入）
14	static void software_fma(const float *a, const float *b, const float *c, float *ref) {
15	    for (int i = 0; i < VECTOR_SIZE; ++i) {
16	        ref[i] = fmaf(a[i], b[i], c[i]);
