49	    std::uniform_real_distribution<float> dist(-100.0f, 100.0f);
50	
51	    do {
52	        // 生成随机向量 a, b, c
53	        for (int i = 0; i < VECTOR_SIZE; ++i) {
54	            a[i] = dist(rng);
55	            b[i] = dist(rng);
56	            c[i] = dist(rng);
57	        }
58	
59	        // ---- 硬件 FMA 计算 (NEON) ----
60	        // 将数据分成低4个和高4个元素加载到两个 NEON 向量
61	        float32x4_t va_low  = vld1q_f32(a);
62	        float32x4_t va_high = vld1q_f32(a + 4);
63	        float32x4_t vb_low  = vld1q_f32(b);
64	        float32x4_t vb_high = vld1q_f32(b + 4);
65	        float32x4_t vc_low  = vld1q_f32(c);
66	        float32x4_t vc_high = vld1q_f32(c + 4);
